import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"55、【丰】 离下震上","description":"周易口诀义 - 55、【丰】 离下震上","frontmatter":{"title":"55、【丰】 离下震上","description":"周易口诀义 - 55、【丰】 离下震上"},"headers":[],"relativePath":"zh/classics/koujueyi/057.md","filePath":"zh/classics/koujueyi/057.md"}'),r={name:"zh/classics/koujueyi/057.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_55、【丰】-离下震上" tabindex="-1">55、【丰】 离下震上 <a class="header-anchor" href="#_55、【丰】-离下震上" aria-label="Permalink to “55、【丰】 离下震上”">​</a></h1><p>彖曰：丰，大也。明以动，故丰。「王假之」，尚大也。「勿忧，宜日中」，宜照天下也。日中则昃，月盈则食，天地盈虚，与时消息，而况于人乎？况于鬼神乎？</p><p>象曰：雷电皆至，「丰」。君子以折狱致刑。</p><p>初九：遇其配主，虽旬无咎，往有尚。</p><p>象曰：「虽旬无咎」，过旬灾也。</p><p>六二：丰其蔀，日中见斗。往得疑疾。有孚发若，吉。</p><p>象曰：「有孚发若」，信以发志也。</p><p>九三：丰其沛，日中见沬。折其右肱，无咎。</p><p>象曰：「丰其沛」，不可大事也。「折其右肱」，终不可用也。</p><p>九四，丰其蔀，日中见斗，遇其夷主，吉。</p><p>象曰：「丰其蔀」，位不当也；「日中见斗」，幽不明也；「遇其夷主」，吉行也。</p><p>六五，来章，有庆誉，吉。</p><p>象曰：六五之吉，有庆也。</p><p>上六，丰其屋，蔀其家，𬮭其户，阒其无人，三岁不觌，凶。</p><p>象曰：「丰其屋」，天际翔也；「𬮭其户，阒其无人」，自藏也。</p><p>解读</p><p>「丰亨」者，丰是弘大之名，饶益为义，财德盛大，故谓之「丰」。财多能济于众，德大无所不通，故曰「丰亨」也。「王假之」者，假，至也，王能至于丰大之德，无所不周也。勿忧，宜日中者，勿，无也，德能广大，无所不通，如日之中，盛明照临万国，德备如此，无复忧虑，为天下主，须令微细隐滞者获通「丰亨勿忧」之德，故「宜日中」也。象曰「雷电皆至，丰」者，雷，天威也；电，光辉也；威光并至，所以丰大也。「君子以折狱致刑」者，折，断也；致，至也。君子法天而行，故折断狱讼，须察虚实，至于刑罚，不滥及无辜也。文明以动，不失情理也。</p><p>「初九，遇其配主，虽旬无咎，往有尚」者，以阳应阳，旬为均平也。丰大之世，文明以动，所贵光大，以合时宜。今初九与四俱阳爻，两体均平，安得有咎？故曰遇其配主，虽旬无咎，能相光大，往有嘉尚也。</p><p>「六二，丰其蔀，日中见斗，往得疑疾，有孚发若，吉」者，处丰之时，贵于光显而恶暗昧。今六二以阴之质应五，又阴是重暗之极，故日中盛明，乃见斗星，故曰「丰其蔀，日中见斗」也。蔀者，暧光明之物也。往就于四，四又暗昧，不能启发其明，心生狐疑而不自决。居乎本位，则暗疾未除，往之与来，不免暗疾，故曰「往得疑疾」。然履中居位，处暗不邪，但怀忠信，不为暗疾所累，而能启发其志，故获吉矣，故曰「有孚发若，吉」也。</p><p>九三，丰其沛，日中见沫，折其右肱，无咎。沛，幡幔，御蔽光明之物也。「沬」是微暗不明之谓也。九三应在上六，志在乎阴，虽免丰蔀见斗，愈乎以阴处阴，而犹丰沛见沬，是日中盛明而见微沬矣，故曰：「丰其沛，日中见沬」。处丰大之时，而见物微沬，斯则不可施于大事。其犹人之所用，在于左右之肱，今右肱既折，况复见物微沬，只可自守而已，乃得无咎，故曰：「折其右肱，无咎。」为施明即见昧，施用则折肱矣。</p><p>「九四，丰其蔀，日中见斗，遇其夷主，吉」者，九四以阳居阴而怀暗昧，如日中见斗也。夷，平也。应在初九，以阳适阳，二体均平，能相显发，若遇初九夷主，所以获吉，故曰：「遇其夷主，吉」也。</p><p>「六五来章，有庆誉，吉」者，以阴之质来居阳位，是暗而求明。既居尊位，能获章美庆誉，所以吉，是光大彰显其德矣。</p><p>「上六，丰其屋，蔀其家，𬮭其户，阒其无人，三岁不觌，凶」者，屋者，藏阴隐之处。上六以阴处外而不居其位，即是幽隐之人，绝迹深藏者。既是藏隐，恐为人所见，故丰厚其屋，而又蔀覆其家。假使𬮭觑其户，隐翳之深，而阒寂不见其人，故曰：「丰其屋，蔀其家，阒其户，阒其无人」也。亦是弃其所止，外处深藏，以高其行。然处丰大之时，即是明君之德，光被天下，野无遗贤，固合睹斯明代，居位佐时，共施政事，而反以自隐三年者，丰道已成而犹不见，所以致凶。治道未济，隐藏犹可；治道既济，何为？藏身不出，失时尚凶，况复更藏，凶其宜也。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
